def double_values_above_threshold(data: dict[str, int], threshold: int = 5) -> dict[str, int]:
    """Return a new dict with values doubled for entries exceeding the threshold."""
    return {
        key: value * 2
        for key, value in data.items()
        if value > threshold
    }
```
